Find the bug:
```c
#include <pthread.h>
#include <stdio.h>

static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
static int balance = 100;

void *withdraw(void *arg) {
    int amount = *(int *)arg;
    pthread_mutex_lock(&m);
    if (balance < amount)
        return NULL;
    balance -= amount;
    pthread_mutex_unlock(&m);
    return NULL;
}

int main(void) {
    pthread_t a, b;
    int x = 150, y = 30;
    pthread_create(&a, NULL, withdraw, &x);
    pthread_create(&b, NULL, withdraw, &y);
    pthread_join(a, NULL);
    pthread_join(b, NULL);
    printf("%d\n", balance);
    return 0;
}
```

