Is this bounded buffer correct?
```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

#define SIZE 8
#define ITEMS 1000

static int buf[SIZE];
static int in, out;
static sem_t empty, full;
static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;

static void *producer(void *arg) {
    (void)arg;
    for (int i = 0; i < ITEMS; i++) {
        sem_wait(&empty);
        pthread_mutex_lock(&m);
        buf[in] = i;
        in = (in + 1) % SIZE;
        pthread_mutex_unlock(&m);
        sem_post(&full);
    }
    return NULL;
}

static void *consumer(void *arg) {
    long sum = 0;
    (void)arg;
    for (int i = 0; i < ITEMS; i++) {
        sem_wait(&full);
        pthread_mutex_lock(&m);
        sum += buf[out];
        out = (out + 1) % SIZE;
        pthread_mutex_unlock(&m);
        sem_post(&empty);
    }
    printf("sum = %ld\n", sum);
    return NULL;
}

int main(void) {
    pthread_t p, c;
    sem_init(&empty, 0, SIZE);
    sem_init(&full, 0, 0);
    pthread_create(&p, NULL, producer, NULL);
    pthread_create(&c, NULL, consumer, NULL);
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    return 0;
}
```

